// ═══════════════════════════════════════════════════════════════════════════
// n8n Function Node: HMAC Verification + Payload Validation
// ═══════════════════════════════════════════════════════════════════════════
// ARCHITECTURE: This node performs two-phase validation:
//   Phase 1: HMAC-SHA256 signature verification (tamper detection)
//   Phase 2: Payload structure validation (data contract enforcement)
//
// Error handling returns granular error codes:
//   MISSING_SIGNATURE  — No signature field in payload
//   INVALID_SIGNATURE  — HMAC mismatch (potential tampering)
//   MALFORMED_PAYLOAD  — Missing required xAPI fields
// ═══════════════════════════════════════════════════════════════════════════

const crypto = require('crypto');

// Pull shared secret from environment variable
const HMAC_SECRET = $env.HMAC_SECRET;
if (!HMAC_SECRET || HMAC_SECRET === 'CHANGE_ME') {
  throw new Error('[CONFIG_ERROR] HMAC_SECRET environment variable is not set or is still the default.');
}

const payload = $input.first().json;

// ── Phase 1: HMAC Signature Verification ────────────────────────────────
const receivedSig = payload.signature;
if (!receivedSig) {
  throw new Error('[MISSING_SIGNATURE] No HMAC signature found in payload.');
}

if (typeof receivedSig !== 'string' || !/^[a-f0-9]{64}$/i.test(receivedSig)) {
  throw new Error('[INVALID_SIGNATURE] Signature is not a valid SHA-256 hex digest.');
}

// Build canonical body (everything except signature)
const { signature, ...body } = payload;
const canonicalBody = JSON.stringify(body);

// Compute expected HMAC-SHA256
const expectedSig = crypto
  .createHmac('sha256', HMAC_SECRET)
  .update(canonicalBody)
  .digest('hex');

// Constant-time comparison to prevent timing attacks
try {
  const sigMatch = crypto.timingSafeEqual(
    Buffer.from(receivedSig, 'hex'),
    Buffer.from(expectedSig, 'hex')
  );
  if (!sigMatch) {
    throw new Error('[INVALID_SIGNATURE] HMAC verification failed — payload may be tampered.');
  }
} catch (e) {
  if (e.message.includes('INVALID_SIGNATURE')) throw e;
  throw new Error('[INVALID_SIGNATURE] Signature comparison failed: ' + e.message);
}

// ── Phase 2: Payload Structure Validation ───────────────────────────────
const requiredFields = ['actor', 'verb', 'object', 'result', 'timestamp'];
const missingFields = requiredFields.filter(f => !body[f]);

if (missingFields.length > 0) {
  throw new Error(`[MALFORMED_PAYLOAD] Missing required fields: ${missingFields.join(', ')}`);
}

// Validate actor has required sub-fields
if (!body.actor?.mbox || !body.actor?.name) {
  throw new Error('[MALFORMED_PAYLOAD] actor must contain mbox and name fields.');
}

// Validate result has score
if (!body.result?.score || typeof body.result.score.raw !== 'number') {
  throw new Error('[MALFORMED_PAYLOAD] result.score.raw must be a number.');
}

// ── Pass verified payload downstream ────────────────────────────────────
return [
  {
    json: {
      ...body,
      _verified: true,
      _signature: receivedSig,
      _verified_at: new Date().toISOString(),
    },
  },
];

// ═══════════════════════════════════════════════════════════════════════════
// Error Logger — Captures failed telemetry for debugging and auditing.
// ═══════════════════════════════════════════════════════════════════════════
// ARCHITECTURE: This node runs when verification/validation fails.
// It extracts the error code and original payload for dead-letter analysis.
//
// In production, this could be extended to:
//   - Insert into a telemetry_errors table
//   - Send alerts to a monitoring system (Slack, PagerDuty)
//   - Write to a dead-letter queue for retry
// ═══════════════════════════════════════════════════════════════════════════

const input = $input.first().json;

// Extract error details from the failed Function node
const errorMessage = input.error?.message || 'Unknown verification failure';

// Parse error code from the structured error message format: [CODE] message
const errorCodeMatch = errorMessage.match(/\[(\w+)\]/);
const errorCode = errorCodeMatch ? errorCodeMatch[1] : 'UNKNOWN_ERROR';

return [
  {
    json: {
      error_code: errorCode,
      error_message: errorMessage,
      original_payload: input,
      failed_at: new Date().toISOString(),
      source_ip: input.headers?.['x-real-ip'] || 'unknown',
    },
  },
];
